function renderDevices(){const rs=filteredReports(),m=new Map();for(const r of rs){const k=`${vendorId(r)}|${r.gpu?.name}`;if(!m.has(k))m.set(k,[]);m.get(k).push(r)}const rows=[...m.values()].sort((a,b)=>String(a[0].gpu.name).localeCompare(String(b[0].gpu.name))).map(v=>{const r=v[0],apis=[...new Set(v.map(x=>x.vulkan?.deviceApiVersion))].sort().reverse(),drv=[...new Set(v.map(x=>`${x.driver?.name||x.driver?.mode} ${x.driver?.version}`))];return `<tr><td>${esc(r.gpu.name)}</td><td>${esc(vendorDisplay(r))}</td><td>${esc(apis[0]||'Unknown')}</td><td>${esc(drv.length)}</td><td>${esc(v.length)}</td></tr>`});$('#content').innerHTML=table(['Device','Vendor / family / ID','Max API','Driver variants','Reports'],rows);empty(rows.length)}
