function statusOk(c){const s=$('#statusFilter').value;return !s||c.status===s}function aggregateCaps(pred){const rs=filteredReports(),m=new Map();for(const r of rs)for(const c of r.capabilities||[])if(pred(c)&&statusOk(c)){const k=`${c.section}\0${c.name}`;if(!m.has(k))m.set(k,{section:c.section,name:c.name,supported:0,unsupported:0,available:0,unavailable:0,unknown:0,reports:0,valueCounts:new Map(),reportStates:[]});const x=m.get(k);x[c.status]=(x[c.status]||0)+1;x.reports++;const v=String(c.value);x.valueCounts.set(v,(x.valueCounts.get(v)||0)+1);x.reportStates.push({id:r.id,device:r.gpu?.name||'Unknown',status:c.status,value:v})}return {rs,items:[...m.values()].sort((a,b)=>a.section.localeCompare(b.section)||a.name.localeCompare(b.name))}}
