function renderQueues(){const rs=filteredReports(),g=state.queueGroup,status=$('#statusFilter').value,keys=['graphics','compute','transfer','sparse','protected','videoDecode','videoEncode','opticalFlow','dataGraph'],labels={graphics:'Graphics',compute:'Compute',transfer:'Transfer',sparse:'Sparse',protected:'Protected',videoDecode:'Video decode',videoEncode:'Video encode',opticalFlow:'Optical flow',dataGraph:'Data graph'};const picker=groupSelect('Queue capability',g,[['all','All capabilities'],...keys.map(k=>[k,labels[k]])]);const rows=[];for(const r of rs)for(const q of r.queues||[]){const states=keys.map(k=>boolState(q[k]));if(g!=='all'){const st=boolState(q[g]);if(status&&st!==status)continue}else if(status&&!states.includes(status))continue;rows.push(`<tr><td>${esc(r.gpu.name)}</td><td>${esc(q.index)}</td><td>${esc(q.count)}</td><td class="code">${esc(canonicalMask(q.flags,QUEUE_FLAG_BITS))}<div class="table-sub">raw ${esc(q.flags)}</div></td><td>${esc(q.timestampBits)}</td><td class="code">${esc(q.granularity)}</td><td class="code">${esc(canonicalMask(q.videoCodecOperations??0,VIDEO_CODEC_BITS))}<div class="table-sub">raw ${esc(q.videoCodecOperations??0)}</div></td>${keys.map(k=>`<td>${badge(boolState(q[k]))}</td>`).join('')}</tr>`)}$('#content').innerHTML=picker+table(['Device','Family','Count','Flags','Timestamp bits','Granularity','Video codec operations',...keys.map(k=>labels[k])],rows);bindGroup('queueGroup',renderQueues);empty(rows.length)}
const surfaceEntries=(s,kind)=>Object.entries(s.capabilities||{}).filter(([k])=>{const x=k.toLowerCase();if(kind==='transforms')return x.includes('transform');if(kind==='composite')return x.includes('composite')&&x.includes('alpha');if(kind==='usage')return x.includes('usage');if(kind==='capabilities')return !x.includes('transform')&&!(x.includes('composite')&&x.includes('alpha'))&&!x.includes('usage');return true});const stateKv=(k,v,st=semanticStatus(v))=>`<div class="kv"><div class="k">${esc(k)}</div><div class="v state-value">${badge(st)} <span>${esc(v??'Unknown')}</span></div></div>`;function surfaceCards(rs,kind,status){return rs.map(r=>{const s=r.surface||{},entries=[];if(kind==='capabilities'){const av=s.available===null||s.available===undefined?'unknown':s.available?'available':'unavailable',pr=s.presentationSupported===null||s.presentationSupported===undefined?'unknown':s.presentationSupported?'supported':'unsupported';if(!status||av===status)entries.push(stateKv('Available',s.available??'Unknown',av));if(!status||pr===status)entries.push(stateKv('Presentation supported',s.presentationSupported??'Unknown',pr))}for(const [k,v] of surfaceEntries(s,kind)){const st=semanticStatus(v);if(!status||st===status)entries.push(stateKv(k,canonicalSurfaceValue(k,v),st))}return entries.length?`<article class="section-card"><h3>${esc(r.gpu.name)}</h3><div class="kv-grid">${entries.join('')}</div></article>`:''}).filter(Boolean)}
