function renderExtensions(){const rs=filteredReports(),m=new Map(),status=$('#statusFilter').value;for(const r of rs)for(const e of r.extensions||[]){if(!m.has(e.name))m.set(e.name,{name:e.name,count:0,spec:new Set(),scope:new Set()});const x=m.get(e.name);x.count++;x.spec.add(e.specVersion);x.scope.add(e.scope)}const rows=[...m.values()].sort((a,b)=>a.name.localeCompare(b.name)).map(x=>{const unknown=Math.max(0,rs.length-x.count);if(status==='supported'&&!x.count)return'';if(status==='unknown'&&!unknown)return'';return `<tr><td class="code">${esc(x.name)}</td><td>${stateNumber(x.count,'supported')}</td><td>${stateCoverage(x.count,rs.length,'supported')}</td><td>${stateNumber(unknown,'unknown')}</td><td>${stateCoverage(unknown,rs.length,'unknown')}</td><td>${esc([...x.spec].sort((a,b)=>b-a).join(', '))}</td><td>${esc([...x.scope].join(', '))}</td></tr>`}).filter(Boolean);$('#content').innerHTML=table(['Device extension','Supported reports','Supported %','Unknown / not listed','Unknown %','Spec versions','Scope'],rows);empty(rows.length)}
